// Stage 4 unit tests: the iOS 6 image pipeline -- IMG3, AES-256-CBC,
// 'comp' LZSS, the armv7 Mach-O parser, the kernel loader and the dyld
// shared cache reader.
//
// Run: tests/run_desktop_tests.sh   (or link manually with the host g++)
//
// The fixtures (tests/gen/image_fixtures.h, generated by
// scripts/gen_image_fixtures.py) are synthetic: formats that match the real
// kernelcache.release.n90 of the 6.1.3 IPSW byte for byte, content that is
// ours. That is the point -- the pipeline is proven without any Apple bytes,
// exactly the way CI runs it.
//
// The AES implementation is additionally pinned to the NIST SP 800-38A
// F.2.5 known-answer vectors, so no mistake can hide between the generator
// and the decoder.

#include <sys/stat.h>
#include <unistd.h>

#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "hakios/aes256.h"
#include "hakios/dyld_cache.h"
#include "hakios/guest_map.h"
#include "hakios/img3.h"
#include "hakios/kernel_loader.h"
#include "hakios/kernel_lzss.h"
#include "hakios/macho_arm.h"
#include "hakios/storage_memory.h"

#include "gen/image_fixtures.h"

using hakios::Aes256Cbc;
using hakios::DyldSharedCache;
using hakios::Img3;
using hakios::KernelLzss;
using hakios::KernelLoadReport;
using hakios::KernelLoadReport;
using hakios::KernelLoader;
using hakios::MachOArm;
using hakios::StorageMemory;

static int g_failures = 0;

#define CHECK(cond)                                                        \
    do {                                                                   \
        if (!(cond)) {                                                     \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);   \
            ++g_failures;                                                   \
        }                                                                   \
    } while (0)

static std::string test_file(const char* name) {
    static std::string dir;
    if (dir.empty()) {
        char tmpl[] = "/tmp/hakios-image-test-XXXXXX";
        if (!::mkdtemp(tmpl)) {
            std::printf("FAIL: mkdtemp\n");
            std::exit(1);
        }
        dir = tmpl;
    }
    return dir + "/" + name;
}

static void test_aes_nist() {
    // NIST SP 800-38A F.2.5: AES-256 CBC, first two blocks.
    static const uint8_t key[32] = {
        0x60, 0x3D, 0xEB, 0x10, 0x15, 0xCA, 0x71, 0xBE, 0x2B, 0x73, 0xAE, 0xF0,
        0x85, 0x7D, 0x77, 0x81, 0x1F, 0x35, 0x2C, 0x07, 0x3B, 0x61, 0x08, 0xD7,
        0x2D, 0x98, 0x10, 0xA3, 0x09, 0x14, 0xDF, 0xF4};
    static const uint8_t iv[16] = {
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
        0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};
    static const uint8_t ct[32] = {
        0xF5, 0x8C, 0x4C, 0x04, 0xD6, 0xE5, 0xF1, 0xBA, 0x77, 0x9E, 0xAB, 0xFB,
        0x5F, 0x7B, 0xFB, 0xD6, 0x9C, 0xFC, 0x4E, 0x96, 0x7E, 0xDB, 0x80, 0x8D,
        0x67, 0x9F, 0x77, 0x7B, 0xC6, 0x70, 0x2C, 0x7D};
    static const uint8_t pt[32] = {
        0x6B, 0xC1, 0xBE, 0xE2, 0x2E, 0x40, 0x9F, 0x96, 0xE9, 0x3D, 0x7E, 0x11,
        0x73, 0x93, 0x17, 0x2A, 0xAE, 0x2D, 0x8A, 0x57, 0x1E, 0x03, 0xAC, 0x9C,
        0x9E, 0xB7, 0x6F, 0xAC, 0x45, 0xAF, 0x8E, 0x51};
    uint8_t out[32];
    CHECK(Aes256Cbc::decrypt(key, iv, ct, out, sizeof ct));
    CHECK(std::memcmp(out, pt, sizeof pt) == 0);
    CHECK(!Aes256Cbc::decrypt(key, iv, ct, out, 31));  // not a whole block
}

static void test_img3() {
    Img3 img3;
    std::string err;
    CHECK(img3.parse(hakios::fixtures::kImg3Plain,
                     sizeof hakios::fixtures::kImg3Plain, &err));
    CHECK(img3.valid());
    CHECK(img3.ident() == Img3::kIdentKernel);
    uint32_t v = 0;
    CHECK(img3.word_tag(Img3::kTagChip, &v) && v == 0x8930);   // the A4
    CHECK(img3.word_tag(Img3::kTagBord, &v) && v == 0);
    CHECK(img3.word_tag(Img3::kTagSepo, &v) && v == 2);
    CHECK(img3.kbag(1) == nullptr);        // the plain fixture has no KBAG
    size_t dlen = 0;
    const uint8_t* d = img3.data(&dlen);
    CHECK(d && dlen > 336);
    CHECK(KernelLzss::is_compressed(d, dlen));  // DATA is a 'comp' blob

    // encrypted fixture: the KBAG walk must see both crypt states
    Img3 enc;
    CHECK(enc.parse(hakios::fixtures::kImg3Encrypted,
                    sizeof hakios::fixtures::kImg3Encrypted, &err));
    CHECK(enc.kbag(1) != nullptr);
    CHECK(enc.kbag(2) != nullptr);
    CHECK(enc.kbag(1)->aes_type == 0x100);
    CHECK(enc.kbag(1)->key_len == 32);
    CHECK(std::string(enc.describe()).find("encrypted") != std::string::npos);

    // garbage fails loudly, not silently
    std::vector<uint8_t> junk(64, 0xAB);
    CHECK(!img3.parse(junk.data(), junk.size(), &err));
    CHECK(!err.empty());
    err.clear();
    junk.resize(19);                        // shorter than a header
    CHECK(!img3.parse(junk.data(), junk.size(), &err));
    CHECK(!err.empty());
}

static void test_lzss() {
    std::string err;
    std::vector<uint8_t> out;
    CHECK(KernelLzss::decompress(hakios::fixtures::kComp,
                                 sizeof hakios::fixtures::kComp, &out, &err));
    CHECK(out.size() == hakios::fixtures::kMachOSize);
    CHECK(std::memcmp(out.data(), hakios::fixtures::kMachO,
                      hakios::fixtures::kMachOSize) == 0);

    // one flipped byte must fail loudly, not produce a wrong kernel. The
    // adler field is the guarantee: any change of the decoded output breaks
    // it. (A flipped byte inside the stream itself is not a reliable test --
    // early matches point into the ring's all-spaces prelude, where a moved
    // position decodes to the same spaces.)
    std::vector<uint8_t> broken(hakios::fixtures::kComp,
                                hakios::fixtures::kComp + sizeof hakios::fixtures::kComp);
    broken[8] ^= 0x40;                       // the header's adler32 field
    CHECK(!KernelLzss::decompress(broken.data(), broken.size(), &out, &err));
    CHECK(err.find("adler32") != std::string::npos);
    err.clear();

    // a promised size nobody can reach: also loud
    broken.assign(hakios::fixtures::kComp,
                  hakios::fixtures::kComp + sizeof hakios::fixtures::kComp);
    broken[12] ^= 1;                        // uncompressedSize, off by one
    CHECK(!KernelLzss::decompress(broken.data(), broken.size(), &out, &err));
    CHECK(!err.empty());

    // (A flipped byte *inside* the stream is not a reliable corruption test:
    //  early matches point into the ring's all-spaces prelude, where a moved
    //  position decodes to the same spaces. The adler check is what makes any
    //  change of the output loud; flipping the adler itself tests that.)
}

static void test_macho() {
    std::string err;
    MachOArm m;
    CHECK(m.parse(hakios::fixtures::kMachO, sizeof hakios::fixtures::kMachO, &err));
    if (!err.empty()) std::printf("macho: %s\n", err.c_str());
    CHECK(m.valid());
    CHECK(!m.was_fat());
    CHECK(m.cputype() == MachOArm::kCpuTypeArm);
    CHECK(m.cpusubtype() == MachOArm::kCpuSubtypeV7);
    CHECK(m.filetype() == MachOArm::kFiletypeKernel);
    CHECK(m.segments().size() == 3);
    const MachOArm::Segment* text = m.find_segment("__TEXT");
    const MachOArm::Segment* data = m.find_segment("__DATA");
    const MachOArm::Segment* bss = m.find_segment("__BSS");
    CHECK(text && data && bss);
    CHECK(text->vmaddr == hakios::fixtures::kTextVaddr);
    CHECK(data->vmaddr == hakios::fixtures::kDataVaddr);
    CHECK(bss->vmaddr == hakios::fixtures::kBssVaddr);
    CHECK(bss->filesize == 0 && bss->vmsize == 0x2000);
    CHECK(m.has_thread());
    CHECK(m.entry_pc() == hakios::fixtures::kEntryPc);
    CHECK(m.entry_sp() == hakios::fixtures::kEntrySp);
    CHECK(m.entry_cpsr() == 0x13);

    // the same image inside a fat wrapper takes the armv7 slice
    MachOArm f;
    CHECK(f.parse(hakios::fixtures::kMachOFat, sizeof hakios::fixtures::kMachOFat, &err));
    CHECK(f.was_fat());
    CHECK(f.segments().size() == 3);
    CHECK(f.entry_pc() == hakios::fixtures::kEntryPc);

    // a kernel for another machine is rejected in the loader test below
}

static void test_loader() {
    std::string err;
    StorageMemory mem;
    CHECK(mem.create(test_file("guest.img"), hakios::map::kPhysSize));
    mem.write32(hakios::fixtures::kTextVaddr, 0xFFFFFFFF);   // dirt first
    mem.write32(hakios::fixtures::kBssVaddr, 0xFFFFFFFF);

    KernelLoadReport rep;
    CHECK(KernelLoader::load(mem, hakios::fixtures::kImg3Plain,
                             sizeof hakios::fixtures::kImg3Plain, nullptr,
                             &rep, &err));
    CHECK(rep.had_img3);
    CHECK(!rep.was_encrypted);
    CHECK(rep.was_compressed);
    CHECK(rep.entry_pc == hakios::fixtures::kEntryPc);
    CHECK(rep.entry_sp == hakios::fixtures::kEntrySp);
    CHECK(rep.placed.size() == 3);
    CHECK(rep.bytes_copied > 0);

    // __TEXT landed byte for byte
    for (size_t i = 0; i < hakios::fixtures::kTextSize; i++)
        if (mem.read8(hakios::fixtures::kTextVaddr + i) !=
            hakios::fixtures::kMachO[28 + 56 * 3 + 84 + i]) {  // file offset of the code
            CHECK(false);
            break;
        }
    // __DATA landed, and the loader's word is what the CPU will see
    CHECK(mem.read32(hakios::fixtures::kDataVaddr) == hakios::fixtures::kDataWord0);
    // __BSS was zero-filled over the dirt
    CHECK(mem.read32(hakios::fixtures::kBssVaddr) == 0);
    CHECK(mem.read32(hakios::fixtures::kBssVaddr + 0x1FFC) == 0);

    // the fat + bare-Mach-O paths both work without any wrapper
    KernelLoadReport rep2;
    CHECK(KernelLoader::load(mem, hakios::fixtures::kMachOFat,
                             sizeof hakios::fixtures::kMachOFat, nullptr, &rep2, &err));
    CHECK(rep2.was_fat && !rep2.had_img3 && !rep2.was_compressed);

    // the encrypted fixture without a key: the error names the missing step
    KernelLoadReport rep3;
    CHECK(!KernelLoader::load(mem, hakios::fixtures::kImg3Encrypted,
                              sizeof hakios::fixtures::kImg3Encrypted, nullptr,
                              &rep3, &err));
    CHECK(err.find("encrypted") != std::string::npos);
    CHECK(err.find("key") != std::string::npos);
    CHECK(rep3.was_encrypted && !rep3.was_decrypted);

    // with the key: the same bytes land as the plain fixture put there
    err.clear();
    KernelLoader::Key key;
    std::memcpy(key.key, hakios::fixtures::kAesKey, 32);
    std::memcpy(key.iv, hakios::fixtures::kAesIv, 16);
    mem.write32(hakios::fixtures::kTextVaddr, 0);  // dirt, so a pass proves a write
    KernelLoadReport rep4;
    CHECK(KernelLoader::load(mem, hakios::fixtures::kImg3Encrypted,
                             sizeof hakios::fixtures::kImg3Encrypted, &key,
                             &rep4, &err));
    CHECK(rep4.was_encrypted && rep4.was_decrypted);
    CHECK(mem.read32(hakios::fixtures::kDataVaddr) == hakios::fixtures::kDataWord0);
    CHECK(rep4.placed.size() == rep.placed.size());
    CHECK(std::string(rep4.describe()).find("AES-256-CBC") != std::string::npos);

    // a segment that does not fit the emulated iPhone's RAM is refused
    std::vector<uint8_t> alien(hakios::fixtures::kMachO,
                               hakios::fixtures::kMachO + sizeof hakios::fixtures::kMachO);
    alien[28 + 24] = 0x00; alien[28 + 25] = 0x00;   // vmaddr lo
    alien[28 + 26] = 0x00; alien[28 + 27] = 0xC0;   // vmaddr hi: 0xC0000000
    StorageMemory alien_mem;
    CHECK(alien_mem.create(test_file("alien.img"), hakios::map::kPhysSize));
    KernelLoadReport rep5;
    CHECK(!KernelLoader::load(alien_mem, alien.data(), alien.size(), nullptr,
                              &rep5, &err));
    CHECK(err.find("outside the emulated iPhone") != std::string::npos);
}

static void test_dyld_cache() {
    std::string err;
    DyldSharedCache cache;
    CHECK(cache.parse(hakios::fixtures::kDyldCache,
                      sizeof hakios::fixtures::kDyldCache, &err));
    CHECK(cache.valid());
    CHECK(cache.platform() == "armv7");
    CHECK(cache.mappings().size() == 2);
    CHECK(cache.mappings()[0].address == 0x40000000);
    CHECK(cache.images().size() == 3);
    CHECK(cache.images()[0].path == "/usr/lib/libSystem.B.dylib");
    CHECK(cache.images()[1].path.find("SpringBoard") != std::string::npos);
    CHECK(cache.images()[2].path == "/usr/lib/libobjc.A.dylib");
    CHECK(DyldSharedCache::looks_like(hakios::fixtures::kDyldCache,
                                      sizeof hakios::fixtures::kDyldCache));

    // not a cache: loud failure
    std::vector<uint8_t> junk(128, 0x41);
    CHECK(!cache.parse(junk.data(), junk.size(), &err));
    CHECK(!err.empty());
}

int main() {
    test_aes_nist();
    test_img3();
    test_lzss();
    test_macho();
    test_loader();
    test_dyld_cache();
    if (g_failures == 0)
        std::printf("image tests: OK (aes, img3, lzss, macho, loader, dyld cache)\n");
    else
        std::printf("image tests: %d failure(s)\n", g_failures);
    return g_failures ? 1 : 0;
}
